"""Data structures and configuration models for offline backtesting."""

from __future__ import annotations

from dataclasses import dataclass, field
from datetime import UTC, datetime
from enum import StrEnum
from typing import Any

from iqoption_research.research.backtest.payoffs import SettlementResult


class SignalDirection(StrEnum):
    CALL = "call"
    PUT = "put"
    HOLD = "hold"
    FLAT = "flat"


@dataclass(frozen=True, slots=True)
class Signal:
    """Action recommendation generated by a strategy at decision time."""

    direction: SignalDirection
    stake: float | None = None
    horizon_bars: int = 1
    metadata: dict[str, Any] = field(default_factory=dict)

    @property
    def is_actionable(self) -> bool:
        return self.direction in (SignalDirection.CALL, SignalDirection.PUT)


@dataclass(frozen=True, slots=True)
class Position:
    """An active simulated position awaiting expiry or exit."""

    position_id: str
    direction: SignalDirection
    entry_bar_index: int
    entry_ts: int
    entry_price: float
    target_exit_bar_index: int
    stake: float
    spread: float
    slippage: float
    capital_at_entry: float = 0.0
    metadata: dict[str, Any] = field(default_factory=dict)


@dataclass(frozen=True, slots=True)
class TradeRecord:
    """A completed, settled trade record."""

    trade_id: str
    direction: SignalDirection
    entry_bar_index: int
    entry_ts: int
    entry_price: float
    exit_bar_index: int
    exit_ts: int
    exit_price: float
    stake: float
    settlement: SettlementResult
    capital_before: float
    capital_after: float

    @property
    def entry_utc(self) -> str:
        return datetime.fromtimestamp(self.entry_ts, tz=UTC).isoformat()

    @property
    def exit_utc(self) -> str:
        return datetime.fromtimestamp(self.exit_ts, tz=UTC).isoformat()

    @property
    def net_pnl(self) -> float:
        return self.settlement.net_pnl

    @property
    def outcome(self) -> str:
        return self.settlement.outcome.value


@dataclass(frozen=True, slots=True)
class PortfolioState:
    """Snapshot of portfolio virtual balance and exposure."""

    timestamp: int
    cash: float
    equity: float
    open_positions_count: int
    cumulative_net_pnl: float
    drawdown_amount: float
    drawdown_percent: float


@dataclass(frozen=True, slots=True)
class BacktestConfig:
    """Deterministic configuration parameters for an offline backtest run."""

    initial_capital: float = 10000.0
    stake_amount: float = 100.0
    stake_mode: str = "fixed"  # "fixed" | "percent"
    max_open_positions: int = 1
    max_drawdown_stop_ratio: float = 0.50
    latency_bars: int = 0
    slippage_pips: float = 0.0
    spread_pips: float = 0.0
    pip_size: float = 0.0001
    default_horizon_bars: int = 1
